import React from 'react';

const awards = [
  'Presidential Volunteer Service Award – Gold (10/2024)',
  '1st Place Securities & Investments, FBLA (02/2022)'
];

export default function Awards() {
  return (
    <section id="awards" className="py-12">
      <h2 className="text-2xl font-bold mb-4">Awards &amp; Scholarships</h2>
      <div className="flex gap-4">
        {awards.map((a,i) => (
          <span key={i} className="px-3 py-1 bg-yellow-200 rounded-full text-sm">
            {a}
          </span>
        ))}
      </div>
    </section>
  );
}
